-- Owner-approved 2026-11-21 ("1"): a 2014 exercise whose name differs from the catalog exercise it was linked to, and which the old program lists under its own name, is a separate exercise here too.
-- 179 such 2014 exercises (33 'exact', 103 'possible', 43 'strong' links made by name computation) become new catalog exercises:
--   source 'catalog2014', title from the 2014 PDF, category from the old program when it has a real one (else empty = "ללא קטגוריה"), songs from the PDF list (deduped by collection code), no texts, no lines.
-- The six category changes of 14c are undone (the old program keeps those catalog exercises in their original categories).
-- Songs that the 2014 variants had added to the original exercises are removed again when no remaining linked 2014 variant lists the same song (same collection code).
-- Frozen copies before: biodanza.snap_exercises_before14g_20261121, snap_exercise_music_before14g_20261121, snap_c14_exercises_before14g_20261121. Undo: restore from them.
begin;
create table if not exists biodanza.snap_exercises_before14g_20261121 as select * from biodanza.exercises;
create table if not exists biodanza.snap_exercise_music_before14g_20261121 as select * from biodanza.exercise_music;
create table if not exists biodanza.snap_c14_exercises_before14g_20261121 as select * from biodanza.c14_exercises;
alter table biodanza.snap_exercises_before14g_20261121 enable row level security;
alter table biodanza.snap_exercise_music_before14g_20261121 enable row level security;
alter table biodanza.snap_c14_exercises_before14g_20261121 enable row level security;
revoke all on biodanza.snap_exercises_before14g_20261121, biodanza.snap_exercise_music_before14g_20261121, biodanza.snap_c14_exercises_before14g_20261121 from anon, authenticated;
create temp table _t(t text) on commit drop;
