”)'),('Dance of Displacement with Lightness and Coordination'),('Dance of Earth-Air'),('Dance of Eutony'),('Dance of Fluidity'),('Dance of Hippopotamus'),('Dance of Integration Yin-Yang'),('Dance of Opposition - Fight'),('Dance of Pulsation in Pairs'),('Dance of Seduction, Men'),('Dance of Seduction, Women'),('Dance of Shamanic Earth'),('Dance of the Angel of Ecstasy'),('Dance of the Angel of Force'),('Dance of the Hero'),('Dance of the Horse, Synergic Jump'),('Dance of the Snake'),('Dance of Transformation and the Myth of Shiva'),('Dance of Water and Air'),('Dance of Water and Voice'),('Dance of Water in Pairs'),('Dance on Tropical Rhythms'),('Dance Out of Patterns'),('Dance to the Sun'),('Dancing Breathing'),('Dancing in Pairs'),('Divine Breath'),('Encounters'),('Encounters of Hands and Gazes'),('Encounters of Hearts'),('Encounters with Hugs'),('Encounters, Fleeting'),('Encounters, Pulsating'),('Encounters, Transcendental'),('Entering the Dance of the Other'),('Eutony'),('Eutony in a Group of 3'),('Eutony of Pelvis on Group (samba in a group of 5)'),('Evocation and Liberation of Inner Energy (Interior)'),('Expression of Femininity'),('Expression of Sensuality'),('Expressive Dance'),('Expressive Dance of Sadness, Melodic'),('Expressive Dance with Intensity'),('Expressive Dance with Levity'),('Expressive Dance, Melodic (Interpretation of the Melody)'),('Final Dance'),('Fluidity in Pairs'),('Fluidity with Imagines'),('Fluidity, Free'),('G.P., Intimacy'),('G.P., Protecting Life'),('Game in Group'),('Game of Unconventional Contact (caminando caminando)'),('Game One, Two, Three, Four'),('Games of Samba and Vitality in Group'),('Games of Vitality'),('Hands and Sensitive Arms'),('Harmonic Extension'),('Harmonic Opposition'),('Harmonization in Pairs'),('Hugs'),('Integration of Neck and Shoulders'),('Integration of the Three Centers, for Imposition of Hands'),('Integration of the Three Centers, in Pairs'),('Integration of the Three Centers, Motor'),('Liberation of Movement 