update biodanza.exercises e set category = s.category, updated_at = now()
from biodanza.snap_exercises_before14c_20261121 s where s.id = e.id and e.source = 'ibf2012' and s.category <> e.category;

create temp table _new on commit drop as
select c.id as c14_id, c.catalog_exercise_id as old_id, gen_random_uuid() as new_id, c.title_en, c.title_he,
  case when c.category_brush <> '' and c.category_brush in (select category from biodanza.exercises where category <> '') then c.category_brush else '' end as cat, c.raw_sources
from biodanza.c14_exercises c join _t on _t.t = c.title_en join biodanza.exercises e on e.id = c.catalog_exercise_id and e.source = 'ibf2012';
do $c$ begin if (select count(*) from _new) <> 179 then raise exception 'expected 179, got %', (select count(*) from _new); end if; end $c$;

-- remove songs the separate variants had added to the original exercises (before relinking, so "remaining variants" means the ones that stay linked)
delete from biodanza.exercise_music em using biodanza.exercises e, biodanza.music m
where e.id = em.exercise_id and e.source = 'ibf2012' and em.source = 'catalog2014' and m.id = em.music_id
and not exists (
  select 1 from biodanza.c14_exercises c cross join lateral jsonb_array_elements(c.raw_sources) s join biodanza.music sm on sm.id = (s->>'m')::uuid
  where c.catalog_exercise_id = em.exercise_id and c.id not in (select c14_id from _new)
  and regexp_replace(upper(sm.collection),'[ _]|^IBFC','','g') = regexp_replace(upper(m.collection),'[ _]|^IBFC','','g'));

insert into biodanza.exercises (id, source, category, title_he, title_en, raw_sources) select new_id, 'catalog2014', cat, title_he, title_en, '[]'::jsonb from _new;
insert into biodanza.exercise_music (exercise_id, music_id, source)
select distinct on (n.new_id, regexp_replace(upper(m.collection),'[ _]|^IBFC','','g')) n.new_id, m.id, 'catalog2014'
from _new n cross join lateral jsonb_array_elements(n.raw_sources) s join biodanza.music m on m.id = (s->>'m')::uuid
order by n.new_id, regexp_replace(upper(m.collection),'[ _]|^IBFC','','g'), m.id;
update biodanza.c14_exercises c set catalog_exercise_id = n.new_id, catalog_match = 'exact' from _new n where c.id = n.c14_id;
commit;
